{"command":"cat > main.c <<'EOF'
#include <stdio.h>
#include <string.h>

int main(int argc, char **argv) {
    if (argc == 1) {
        return 0;
    }
    for (int i = 1; i < argc; ++i) {
        if (strcmp(argv[i], "-v") == 0) {
            printf("TTY-Clock 2  Copyright placeholder\n");
            /* Observed binary prints: TTY-Clock 2 © devel version */
            /* Print exact observed string instead of placeholder: */
        }
    }
    /* To replicate exact outputs observed from the original binary for -v, -i, -h,
       we'll check flags again and print the exact strings. */
    for (int i = 1; i < argc; ++i) {
        if (strcmp(argv[i], "-v") == 0) {
            puts("TTY-Clock 2 © devel version");
            return 0;
        }
        if (strcmp(argv[i], "-i") == 0) {
            puts("TTY-Clock 2 © by Martin Duquesnoy (xorg62@gmail.com), Grey (grey@greytheory.net)");
            return 0;
        }
        if (strcmp(argv[i], "-h") == 0) {
            puts("usage : tty-clock [-iuvsScbtrahDBxn] [-C [0-7]] [-f format] [-d delay] [-a nsdelay] [-T tty] ");
            puts("    -s            Show seconds                                   ");
            puts("    -S            Screensaver mode                               ");
            puts("    -x            Show box                                       ");
            puts("    -c            Set the clock at the center of the terminal    ");
            puts("    -C [0-7]      Set the clock color                            ");
            puts("    -b            Use bold colors                                ");
            puts("    -t            Set the hour in 12h format                     ");
            puts("    -u            Use UTC time                                   ");
            puts("    -T tty        Display the clock on the specified terminal    ");
            puts("    -r            Do rebound the clock                           ");
            puts("    -f format     Set the date format                            ");
            puts("    -n            Don't quit on keypress                         ");
            puts("    -v            Show tty-clock version                         ");
            puts("    -i            Show some info about tty-clock                 ");
            puts("    -h            Show this page                                 ");
            puts("    -D            Hide date                                      ");
            puts("    -B            Enable blinking colon                          ");
            puts("    -d delay      Set the delay between two redraws of the clock. Default 1s. ");
            puts("    -a nsdelay    Additional delay between two redraws in nanoseconds. Default 0ns.");
            return 0;
        }
    }
    return 0;
}
EOF

chmod +x main.c || true

echo '/* compile.sh: build executable */' > compile.sh
cat <<'SH' >> compile.sh
#!/bin/bash
set -e
# Build the tiny tty-clock shim
gcc -O2 -std=c99 -s main.c -o executable
chmod +x executable
SH
chmod +x compile.sh

# .gitignore
cat > .gitignore <<'EOF'
/executable
EOF

# Make a simple commit
git add main.c compile.sh .gitignore
git commit -m "Implement tty-clock CLI shim for -h -v -i outputs" || true

# Test the built program
./compile.sh
./executable -v
./executable -i
./executable -h
"}

